// What the API scaffolder cannot read from the module specifications and the tables.
// See scaffold-api.mjs.
//
// handWritten   tables whose standard API is written by hand. The scaffolder leaves their files alone
//               and still counts their routes as existing. A resource is taken over this way when it
//               gets rules of its own:
//                 1. list the table here;
//                 2. remove the three-line "Generated by" header from its contract, db-service,
//                    service, route, API client and hooks files;
//                 3. run `pnpm scaffold:api` and export those files from each package's index.ts,
//                    because the generated lists no longer do;
//                 4. edit the files.
//               The scaffolder never deletes a file. One that still carries the header but is no
//               longer generated is listed, and `--check` fails until it is deleted or loses the header.
// tables        per table:
//                 skip     a sentence saying why the standard API does not fit (it is then left to a
//                          hand-written service and shows in the report)
//                 create   false when adding a row needs more than its columns (a number from a
//                          sequence, lines, a posting): the route waits for a hand-written service
//                 server   columns the client never sends, beyond those the scaffolder recognises
//                 input    columns the client does send, although the scaffolder would hold them back
//                 label    the name used in messages, when the entity's name reads badly

export const apiHints = {
  handWritten: [],
  tables: {},
};
